cards:[
 {
  "t": "TIER 1 - EXPECTED OF EVERYONE",
  "q": "1 ▶ Recite the logical order of query evaluation. Why can’t WHERE use a SELECT alias?",
  "a": "FROM → JOIN → WHERE → GROUP BY → HAVING → SELECT → DISTINCT → ORDER BY → LIMIT. WHERE (step 3) runs before SELECT (step 6), ORDER BY (step 8) after — so ORDER BY can use aliases, WHERE cannot. (Part 2)"
 },
 {
  "t": "TIER 1 - EXPECTED OF EVERYONE",
  "q": "2 ▶ A 100-row table has 20 NULL cities; WHERE city <> ‘IN’ returns 50 of 80 non-null. Where are the rest?",
  "a": "Dropped — NULL yields UNKNOWN and WHERE keeps only TRUE. The two queries never sum to the table, silently. Test NULL with IS NULL, not = or <>. (Part 2)"
 },
 {
  "t": "TIER 1 - EXPECTED OF EVERYONE",
  "q": "3 ▶ What is a self-join, and why LEFT JOIN for employees-to-manager?",
  "a": "Joining a table to itself with aliases: e LEFT JOIN m ON m.id = e.manager_id. LEFT keeps rows with no match — the CEO has no manager and would vanish under INNER. (Part 4)"
 },
 {
  "t": "TIER 1 - EXPECTED OF EVERYONE",
  "q": "4 ▶ Your LEFT JOIN silently filtered rows to an inner join. The cause and the fix?",
  "a": "You put a condition on the OPTIONAL table in WHERE — its NULL-padded rows evaluate UNKNOWN and drop. Move it into ON. Conditions on the preserved table stay in WHERE. (Part 4)"
 },
 {
  "t": "TIER 1 - EXPECTED OF EVERYONE",
  "q": "5 ▶ What is the NOT IN NULL trap, and the safer alternative?",
  "a": "x NOT IN (1, NULL) is x <> 1 AND x <> NULL — always UNKNOWN, so it returns NOTHING, silently. Use NOT EXISTS (or NOT IN ... WHERE col IS NOT NULL). (Part 6)"
 },
 {
  "t": "TIER 1 - EXPECTED OF EVERYONE",
  "q": "6 ▶ WHERE vs HAVING — when is each evaluated, and which cannot see aggregates?",
  "a": "WHERE filters rows before grouping (step 3); HAVING filters groups after (step 5). WHERE cannot see aggregates like COUNT; HAVING cannot filter single rows efficiently. (Part 5)"
 },
 {
  "t": "TIER 1 - EXPECTED OF EVERYONE",
  "q": "7 ▶ For values 10, 10, 9, what do ROW_NUMBER, RANK, DENSE_RANK assign?",
  "a": "ROW_NUMBER: 1,2,3 (tie broken arbitrarily). RANK: 1,1,3 (gap after tie). DENSE_RANK: 1,1,2 (no gap). The classic trinity question. (Part 6)"
 },
 {
  "t": "TIER 1 - EXPECTED OF EVERYONE",
  "q": "8 ▶ Why are constraints the database defending your data — and what habit pairs with destructive statements?",
  "a": "The database is the LAST line of defense against every code path — scripts, consoles, migrations. Pair with: run the same WHERE as a SELECT first, wrap in a transaction you can ROLLBACK. (Part 7)"
 },
 {
  "t": "TIER 2 - DIFFERENTIATORS",
  "q": "9 ▶ Why can LIKE ‘A%’ use an index but LIKE ‘%A’ cannot — and what else kills indexes?",
  "a": "B-tree leaves are in prefix order with linked ranges — a leading wildcard has no starting point. Function-wrapped columns (YEAR(created_at)) also defeat the index; use range checks. (Parts 3, 9)"
 },
 {
  "t": "TIER 2 - DIFFERENTIATORS",
  "q": "10 ▶ I have an index on (a, b). Which filters can use it?",
  "a": "Filters on a alone or a AND b — generally NOT b alone. Composite index order is lexicographic, like a phone book ordered by last name useless for first-name lookups. (Part 9)"
 },
 {
  "t": "TIER 2 - DIFFERENTIATORS",
  "q": "11 ▶ GROUP BY vs a window function — the entire difference in one sentence?",
  "a": "GROUP BY COLLAPSES rows (10 in → 3 out); window functions keep every row and add a computed column (10 in → 10 out) — so per-customer totals sit next to each order. (Part 6)"
 },
 {
  "t": "TIER 2 - DIFFERENTIATORS",
  "q": "12 ▶ Why is the average of per-city averages wrong — and how do you compute several metrics in one scan?",
  "a": "Averaging averages ignores differing group sizes — aggregate from base rows. Use COUNT(*) FILTER (WHERE ...) or SUM(CASE WHEN ...) for multiple metrics in a single pass. (Part 5)"
 },
 {
  "t": "TIER 2 - DIFFERENTIATORS",
  "q": "13 ▶ EXPLAIN vs EXPLAIN ANALYZE — which one runs the query, and when do estimates lie?",
  "a": "EXPLAIN ANALYZE EXECUTES and shows real counts/timings versus estimates (careful with UPDATE/DELETE — wrap in a rolled-back transaction). When estimates diverge wildly: stale statistics → ANALYZE. (Part 9)"
 },
 {
  "t": "TIER 2 - DIFFERENTIATORS",
  "q": "14 ▶ Why are CTEs the readability tool, and what recursive power do they hide?",
  "a": "CTEs name intermediate results so a complex query reads top-to-bottom like the evaluation pipeline instead of inside-out nesting — and WITH RECURSIVE walks hierarchies and graphs. (Part 6)"
 },
 {
  "t": "TIER 3 - SENIOR SIGNAL",
  "q": "15 ▶ You store money as DOUBLE PRECISION and total 0.1 + 0.2 → 0.30000000000000004. Diagnose.",
  "a": "Floats are binary approximations — exact decimal arithmetic is impossible (money, tariffs, sums). Store NUMERIC(12,2)/DECIMAL. Types are constraints the engine enforces. (Part 3)"
 },
 {
  "t": "TIER 3 - SENIOR SIGNAL",
  "q": "16 ▶ Walk the lost update and its three fixes.",
  "a": "Two transactions read value → compute in the app → write; the second overwrites the first SILENTLY at READ COMMITTED. Fixes: do arithmetic in SQL (SET balance = balance - 500), SELECT ... FOR UPDATE, make it impossible (CHECK), or SERIALIZABLE + retry. (Part 11)"
 },
 {
  "t": "TIER 3 - SENIOR SIGNAL",
  "q": "17 ▶ Narrate the query lifecycle, parser to executor.",
  "a": "Parser (string → AST) → analyzer (tables/columns/types) → rewriter (flatten subqueries, push predicates) → planner/optimizer (enumerate plans, cost with statistics) → executor (pull rows through the plan tree). (Part 10)"
 },
 {
  "t": "TIER 3 - SENIOR SIGNAL",
  "q": "18 ▶ When does row-oriented storage lose to columnar — and why?",
  "a": "Analytics reads FEW columns across MANY rows — row stores drag every column (and PAY the I/O) per 8KB page; columnar compresses and scans only the needed columns, trading single-row writes/updates away. (Parts 10, 12)"
 }
],
